// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Validation address_id ---
if (!body.address_id) {
  return {
    error: true,
    error_code: 'MISSING_ADDRESS_ID',
    message: 'Le champ "address_id" est requis'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    // azy.daily#643 — le jeton de service TRANSITE, il n'est pas exigé.
    //
    // Le rendre obligatoire ici casserait les 13 outils AVANT que la route d'api ne
    // l'exige. On le laisse donc passer tel quel, `null` s'il est absent — et c'est
    // précisément ce que l'essai conjoint doit révéler : si MCP ne le relaie pas,
    // `jeton_transmis` vaudra false et api verra un appel sans jeton.
    //
    // ⚠️ AUCUN repli sur `$env`. Trois workflows du parc font
    // `body.backend_service_token || $env.BACKEND_SERVICE_TOKEN` : ce repli ferait
    // MENTIR l'essai, qui réussirait même si rien ne traverse la chaîne.
    backend_service_token: body.backend_service_token || null,
    discord_user_id: body.discord_user_id,
    address_id: body.address_id,
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================


// ── azy.daily#643 — lire le STATUT RÉEL, pour que l'essai puisse CONCLURE ─────
//
// Avant : le nœud HTTP portait `onError: continueErrorOutput` et sa sortie
// d'erreur n'était BRANCHÉE NULLE PART. Un échec interrompait donc le workflow
// avant tout `respondToWebhook`, et n8n fermait la requête avec 200 et un corps
// VIDE (n8n-workflows#467). Mesuré sur les 13 outils e-commerce.
//
// ⚠️ Conséquence pour l'essai conjoint avec api : le jour où leur route exige un
// jeton, un 401 serait ressorti en « 200 sans rien ». L'essai « est-ce que ça
// passe ? » aurait répondu OUI sur un refus. Il fallait corriger ceci AVANT de
// tester, pas après.
//
// Le nœud porte maintenant fullResponse + neverError (il émet { statusCode, body }),
// et onError: continueRegularOutput pour les pannes de transport, où n8n n'émet
// AUCUN statusCode — le statut réel n'existe alors que dans le message, sous la
// forme « 401 - {...} ».
function statutReel643(entree) {
  if (typeof entree.statusCode === 'number') return entree.statusCode;
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  if (m) return parseInt(m[1], 10);
  return (entree.error || entree.code) ? 502 : 200;
}
function corpsApi643(entree) {
  if (entree.body !== undefined && entree.body !== null) return entree.body;
  const brut = String((entree.error && entree.error.message) || entree.message || '');
  const i = brut.indexOf('{'), j = brut.lastIndexOf('}');
  if (i < 0 || j <= i) return {};
  const bloc = brut.slice(i, j + 1);
  for (const essai of [bloc, bloc.replace(/\\"/g, '"').replace(/\\\\/g, '\\')]) {
    try { const o = JSON.parse(essai); if (o && typeof o === 'object') return o; } catch (e) {}
  }
  return {};
}
function messageApi643(corps, defaut) {
  if (!corps) return defaut;
  const d = corps.detail;
  if (typeof d === 'string' && d) return d;
  if (Array.isArray(d) && d.length) return d.map(e => (e && e.msg) || JSON.stringify(e)).join(' ; ').slice(0, 300);
  if (typeof corps.message === 'string' && corps.message) return corps.message;
  if (typeof corps.error === 'string' && corps.error) return corps.error;
  if (corps.error && typeof corps.error.message === 'string') return corps.error.message;
  return defaut;
}

const enveloppe = $input.first().json;
const validationData = $('Validate Input').first().json;
const statut643 = statutReel643(enveloppe);
const apiResponse = corpsApi643(enveloppe);
const jetonTransmis643 = !!validationData.data.backend_service_token;

// --- Check API errors ---
if (statut643 >= 400 || enveloppe.error || apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: statut643 === 401 || statut643 === 403 ? 'SERVICE_TOKEN_REJECTED'
            : (apiResponse.error?.code || 'API_ERROR'),
      message: messageApi643(apiResponse, apiResponse.error?.message || 'Erreur API'),
      http_status: statut643 >= 400 ? statut643 : (apiResponse.error?.http_status || 502)
    },
    // Témoin d'essai : dit si NOUS avons transmis un jeton. Sans lui, un 401 ne
    // distinguerait pas « MCP ne l'a pas relayé » de « api l'a refusé ».
    jeton_transmis: jetonTransmis643,
    _trace: { http_status: statut643 }
  };
}

// --- Success response ---
return {
  success: true,
  message: 'Adresse par defaut mise a jour',
  default_address_id: validationData.data.address_id
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

